}

var errorsJoin = func(errs []error) error {
	return fmt.Errorf("%w", joinError(errs))
}

type joinError []error

func (e joinError) Error() string {
	if len(e) == 0 {
		return ""
	}
	msg := e[0].Error()
	for _, err := range e[1:] {
		msg += "\n" + err.Error()
	}
	return msg
}

func (e joinError) Unwrap() []error { return []error(e) }

